#s91 .stage{background:#FAFBFC;color:#172B4D}
#s91 .d-nav{background:#fff;border:1px solid #DFE1E6;border-radius:3px}
#s91 .d-logo{font-weight:700;color:#0052CC}
#s91 .d-links span{opacity:.65;color:#5E6C84}#s91 .d-links span:hover{opacity:1;color:#0052CC}
#s91 .d-h{font-weight:600;font-size:19px}
#s91 .d-p{color:#5E6C84}
